-- ADDITIVE migration: keeps existing admin_users and Deal Hunter tables.
create extension if not exists pgcrypto;
create table if not exists public.marketplace_settings(id uuid primary key default gen_random_uuid(),site_name text not null default 'Digital Rental Hub AU',support_email text,market text not null default 'AU' check(market='AU'),currency text not null default 'AUD' check(currency='AUD'),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.marketplace_settings(site_name,market,currency) select 'Digital Rental Hub AU','AU','AUD' where not exists(select 1 from public.marketplace_settings);
create table if not exists public.offerings(id uuid primary key default gen_random_uuid(),title text not null,slug text unique,offering_type text not null check(offering_type in('digital_rental','digital_product','service')),platform text,description text,image_url text,daily_rate numeric(10,2) not null default 0 check(daily_rate>=0),weekly_rate numeric(10,2) not null default 0 check(weekly_rate>=0),base_price numeric(10,2) not null default 0 check(base_price>=0),capacity integer not null default 1 check(capacity>=1),min_rental_days integer not null default 1 check(min_rental_days>=1),max_rental_days integer not null default 14 check(max_rental_days>=min_rental_days),active boolean not null default true,market text not null default 'AU' check(market='AU'),currency text not null default 'AUD' check(currency='AUD'),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create sequence if not exists public.booking_number_seq start 1;
create table if not exists public.bookings(id uuid primary key default gen_random_uuid(),booking_number text unique not null default('DRH-'||to_char(current_date,'YYYY')||'-'||lpad(nextval('public.booking_number_seq')::text,6,'0')),offering_id uuid not null references public.offerings(id),customer_name text not null,customer_email text not null,customer_phone text,quantity integer not null default 1 check(quantity>=1),start_date date,end_date date,notes text,total_amount numeric(10,2) not null default 0,currency text not null default 'AUD' check(currency='AUD'),status text not null default 'confirmed' check(status in('pending','confirmed','in_progress','completed','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint rental_dates_valid check((start_date is null and end_date is null) or(start_date is not null and end_date is not null and end_date>=start_date)));
create index if not exists bookings_offering_dates_idx on public.bookings(offering_id,start_date,end_date);
create index if not exists bookings_email_idx on public.bookings(lower(customer_email));
create or replace function public.is_marketplace_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admin_users a where a.user_id=auth.uid())$$;
alter table public.marketplace_settings enable row level security;alter table public.offerings enable row level security;alter table public.bookings enable row level security;
drop policy if exists "public read marketplace settings" on public.marketplace_settings;create policy "public read marketplace settings" on public.marketplace_settings for select using(true);
drop policy if exists "admin manage marketplace settings" on public.marketplace_settings;create policy "admin manage marketplace settings" on public.marketplace_settings for all using(public.is_marketplace_admin()) with check(public.is_marketplace_admin());
drop policy if exists "public read active offerings" on public.offerings;create policy "public read active offerings" on public.offerings for select using(active=true or public.is_marketplace_admin());
drop policy if exists "admin manage offerings" on public.offerings;create policy "admin manage offerings" on public.offerings for all using(public.is_marketplace_admin()) with check(public.is_marketplace_admin());
drop policy if exists "admin read bookings" on public.bookings;create policy "admin read bookings" on public.bookings for select using(public.is_marketplace_admin());
drop policy if exists "admin update bookings" on public.bookings;create policy "admin update bookings" on public.bookings for update using(public.is_marketplace_admin()) with check(public.is_marketplace_admin());
create or replace function public.available_capacity(p_offering_id uuid,p_start_date date,p_end_date date) returns integer language plpgsql stable security definer set search_path=public as $$declare v_capacity integer;v_used integer;begin select capacity into v_capacity from offerings where id=p_offering_id and active=true;if v_capacity is null then return 0;end if;select coalesce(sum(quantity),0)::integer into v_used from bookings where offering_id=p_offering_id and status in('pending','confirmed','in_progress') and start_date<=p_end_date and end_date>=p_start_date;return greatest(v_capacity-v_used,0);end$$;
create or replace function public.create_public_booking(p_offering_id uuid,p_start_date date,p_end_date date,p_customer_name text,p_customer_email text,p_customer_phone text default null,p_quantity integer default 1,p_notes text default null) returns table(booking_id uuid,booking_number text,total_amount numeric,status text) language plpgsql security definer set search_path=public as $$declare v_offer offerings%rowtype;v_days integer;v_weeks integer;v_rem integer;v_total numeric(10,2);v_available integer;v_booking bookings%rowtype;begin if p_customer_name is null or length(trim(p_customer_name))<2 then raise exception 'Customer name is required';end if;if p_customer_email is null or position('@' in p_customer_email)<2 then raise exception 'A valid email is required';end if;if p_quantity<1 then raise exception 'Quantity must be at least 1';end if;select * into v_offer from offerings where id=p_offering_id and active=true;if not found then raise exception 'Offering is not available';end if;perform pg_advisory_xact_lock(hashtext(p_offering_id::text));if v_offer.offering_type='digital_rental' then if p_start_date is null or p_end_date is null then raise exception 'Rental dates are required';end if;if p_end_date<p_start_date then raise exception 'End date cannot be before start date';end if;v_days:=(p_end_date-p_start_date)+1;if v_days<v_offer.min_rental_days or v_days>v_offer.max_rental_days then raise exception 'Rental must be between % and % days',v_offer.min_rental_days,v_offer.max_rental_days;end if;v_available:=available_capacity(p_offering_id,p_start_date,p_end_date);if v_available<p_quantity then raise exception 'Selected dates are no longer available';end if;v_weeks:=floor(v_days/7.0);v_rem:=v_days%7;if v_offer.weekly_rate>0 then v_total:=(v_weeks*v_offer.weekly_rate)+(v_rem*v_offer.daily_rate);else v_total:=v_days*v_offer.daily_rate;end if;v_total:=v_total*p_quantity;else if p_quantity>v_offer.capacity then raise exception 'Requested quantity is unavailable';end if;v_total:=v_offer.base_price*p_quantity;p_start_date:=null;p_end_date:=null;end if;insert into bookings(offering_id,customer_name,customer_email,customer_phone,quantity,start_date,end_date,notes,total_amount,status) values(p_offering_id,trim(p_customer_name),lower(trim(p_customer_email)),nullif(trim(p_customer_phone),''),p_quantity,p_start_date,p_end_date,nullif(trim(p_notes),''),v_total,'confirmed') returning * into v_booking;return query select v_booking.id,v_booking.booking_number,v_booking.total_amount,v_booking.status;end$$;
create or replace function public.track_booking(p_booking_number text,p_email text) returns table(booking_number text,offering_title text,status text,start_date date,end_date date,total_amount numeric) language sql stable security definer set search_path=public as $$select b.booking_number,o.title,b.status,b.start_date,b.end_date,b.total_amount from bookings b join offerings o on o.id=b.offering_id where b.booking_number=upper(trim(p_booking_number)) and lower(b.customer_email)=lower(trim(p_email)) limit 1$$;
grant execute on function public.available_capacity(uuid,date,date) to anon,authenticated;grant execute on function public.create_public_booking(uuid,date,date,text,text,text,integer,text) to anon,authenticated;grant execute on function public.track_booking(text,text) to anon,authenticated;
